<?php
require __DIR__.'/config.php'; require_role(['admin','teacher']);$students=read_json('students');$results=read_json('results');$attendance=read_json('attendance');$schoolAvg=[];
foreach($students as $st)$schoolAvg[]=['name'=>$st['name']??'','avg'=>average_for_student($results,(int)$st['id'])];
$valid=array_values(array_filter($schoolAvg,fn($x)=>$x['avg']!==null));$overall=$valid?round(array_sum(array_column($valid,'avg'))/count($valid),1):null;$ar=[];foreach($students as $st){$r=attendance_rate_for_student($attendance,(int)$st['id']);if($r!==null)$ar[]=$r;}$attAvg=$ar?round(array_sum($ar)/count($ar),1):null;
