</head><body class="rf-dynamic"><div class="wrap"><p><a href="school.php">← School Management</a></p><h1>Academic Analytics</h1><div class="stats"><div class="card"><div class="metric"><?=h($overall===null?'—':$overall.'%')?></div><p>Average across learners with results</p></div><div class="card"><div class="metric"><?=h($attAvg===null?'—':$attAvg.'%')?></div><p>Average attendance</p></div><div class="card"><div class="metric"><?=count($students)?></div><p>Total learners</p></div></div><div class="card" style="margin-top:18px"><h2>Learner performance</h2><table class="table"><tr><th>Learner</th><th>Average</th><th>Visual</th></tr><?php usort($schoolAvg,fn($a,$b)=>($b['avg']??-1)<=>($a['avg']??-1));foreach($schoolAvg as $x):?><tr><td><?=h($x['name'])?></td><td><?=h($x['avg']===null?'No results':$x['avg'].'%')?></td><td><div class="bg"><div class="bar" style="width:<?=h((string)($x['avg']??0))?>%"></div></div></td></tr><?php endforeach;?></table></div></div><script src="assets/dynamic-site.js"></script>
